CREATE TABLE IF NOT EXISTS users(
  id BIGSERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('caissier','siege','admin')), store TEXT, caisse INTEGER,
  pw_hash TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS stores(code TEXT PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL, caisses INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(sku TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL CHECK(price > 0), threshold INTEGER NOT NULL DEFAULT 40 CHECK(threshold >= 0));
CREATE TABLE IF NOT EXISTS stock(store TEXT NOT NULL REFERENCES stores(code), sku TEXT NOT NULL REFERENCES products(sku), qty INTEGER NOT NULL CHECK(qty >= 0), PRIMARY KEY(store, sku));
CREATE TABLE IF NOT EXISTS sales(id_vente TEXT PRIMARY KEY, store TEXT NOT NULL, caisse INTEGER NOT NULL, cashier TEXT, ts TEXT NOT NULL, received_at TEXT NOT NULL, total INTEGER NOT NULL, nb_items INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_sales_ts ON sales(ts);
CREATE TABLE IF NOT EXISTS sale_lines(id BIGSERIAL PRIMARY KEY, id_vente TEXT NOT NULL REFERENCES sales(id_vente), sku TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty > 0), price INTEGER NOT NULL CHECK(price >= 0));
CREATE INDEX IF NOT EXISTS ix_lines_sale ON sale_lines(id_vente);
CREATE TABLE IF NOT EXISTS processed(id_vente TEXT PRIMARY KEY, at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id BIGSERIAL PRIMARY KEY, ts TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_events_kind_ts ON events(kind, ts);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
